 288 export const BuilderDocument = ({
 289     project,
 290     viewMode,
 291     onMarkdownChange,
 292     activeChapterId,
 293     setActiveChapterId,
 294     selectedSectionIds,
 295     handleActiveSectionChange,
 296     summarizeMutation,
 297     expandMutation,
 298     rewriteMutation,
 299     rewriteStyles,
 300 }: DocumentProps) => {
 301     const [hoveredItemId, setHoveredItemId] = useState<string | null>(null);
 302     const hoverTimeoutRef = useRef<NodeJS.Timeout | null>(null);
 303 
 304     const allSections = useMemo(() =>
 305         project.content.flatMap(item =>
 306             item instanceof Chapter ? item.sections : item instanceof Section ? [item] : []
 307         ),
 308     [project.content]);
 309 
 310     const handleItemMouseEnter = useCallback((id: string) => {
 311         if (hoverTimeoutRef.current) clearTimeout(hoverTimeoutRef.current);
 312         setHoveredItemId(id);
 313     }, []);
 314 
 315     const handleItemMouseLeave = useCallback(() => {
 316         hoverTimeoutRef.current = setTimeout(() => {
 317             setHoveredItemId(null);
 318         }, 300);
 319     }, []);
 320 
 321     useEffect(() => () => {
 322         if (hoverTimeoutRef.current) {
 323             clearTimeout(hoverTimeoutRef.current);
 324             hoverTimeoutRef.current = null;
 325         }
 326     }, []);
 327 
 328     const handleActiveItemDetect = useCallback((headingText: string | null) => {
 329         if (!headingText) return;
 330 
 331         const matched = allSections.find(section => section.title.trim() === headingText.trim());
 332         if (matched) {
 333             handleActiveSectionChange(matched.id);
 334             return;
 335         }
 336 
 337         const matchedChapter = project.content.find(
 338             item => item instanceof Chapter && item.title.trim() === headingText.trim()
 339         );
 340         if (matchedChapter instanceof Chapter) {
 341             setActiveChapterId(matchedChapter.id);
 342         }
 343     }, [allSections, handleActiveSectionChange, project.content, setActiveChapterId]);
 344 
 345     const handleSelectChapterSections = useCallback((chapter: Chapter) => {
 346         setActiveChapterId(chapter.id);
 347         chapter.sections.forEach(section => handleActiveSectionChange(section.id, true));
 348     }, [handleActiveSectionChange, setActiveChapterId]);
 349 
 350     const handleSelectChapter = useCallback((chapterId: string) => {
 351         setActiveChapterId(chapterId);
 352         setHoveredItemId(null);
 353     }, [setActiveChapterId]);
 354 
 355     const handleSectionClick = useCallback((sectionId: string) => {
 356         handleActiveSectionChange(sectionId);
 357     }, [handleActiveSectionChange]);
 358 
 359     const handleSectionEdit = useCallback((sectionId: string) => {
 360         handleActiveSectionChange(sectionId);
 361         setHoveredItemId(null);
 362     }, [handleActiveSectionChange]);
 363 
 364     const handleSummarize = useCallback((section: Section) => {
 365         summarizeMutation?.mutate?.({ text: section.content, sectionId: section.id } as any);
 366     }, [summarizeMutation]);
 367 
 368     const handleExpand = useCallback((section: Section) => {
 369         expandMutation?.mutate?.({ text: section.content, sectionId: section.id } as any);
 370     }, [expandMutation]);
 371 
 372     const handleRewrite = useCallback((section: Section, style: string) => {
 373         rewriteMutation?.mutate?.({ text: section.content, style, sectionId: section.id } as any);
 374     }, [rewriteMutation]);
 375 
 376     return (
 377         <div className="pb-32">
 378             {/* Editor / preview switch retains selection context */}
 379             {viewMode === 'edit' ? (
 380                 <MarkdownEditor
 381                     content={project.fullMarkdownContent}
 382                     onChange={onMarkdownChange}
 383                     onDebouncedChange={onMarkdownChange}
 384                     onActiveItemDetect={handleActiveItemDetect}
 385                 />
 386             ) : (
 387                 <div className="space-y-12">
 388                     {project.content.map((item, index) => {
 389                         const isPreview = viewMode === 'preview';
 390 
 391                         if (item instanceof Chapter) {
 392                             return (
 393                                 <ChapterPreview
 394                                     key={item.id}
 395                                     item={item}
 396                                     index={index}
 397                                     isPreview={isPreview}
 398                                     activeChapterId={activeChapterId}
 399                                     hoveredItemId={hoveredItemId}
 400                                     onHoverEnter={handleItemMouseEnter}
 401                                     onHoverLeave={handleItemMouseLeave}
 402                                     onSelectChapter={handleSelectChapter}
 403                                     onSelectChapterSections={handleSelectChapterSections}
 404                                     handleActiveSectionChange={handleActiveSectionChange}
 405                                 />
 406                             );
 407                         }
 408 
 409                         if (item instanceof Section) {
 410                             const isSummarizing = Boolean(
 411                                 summarizeMutation?.isPending && summarizeMutation?.variables?.sectionId === item.id
 412                             );
 413                             const isExpanding = Boolean(
 414                                 expandMutation?.isPending && expandMutation?.variables?.sectionId === item.id
 415                             );
 416                             const isRewriting = Boolean(
 417                                 rewriteMutation?.isPending && rewriteMutation?.variables?.sectionId === item.id
 418                             );
 419                             const isActiveSectionInEdit = !isPreview && selectedSectionIds.includes(item.id);
 420 
 421                             return (
 422                                 <SectionPreview
 423                                     key={item.id}
 424                                     item={item}
 425                                     index={index}
 426                                     isPreview={isPreview}
 427                                     hoveredItemId={hoveredItemId}
 428                                     isActiveSectionInEdit={isActiveSectionInEdit}
 429                                     isSummarizing={isSummarizing}
 430                                     isExpanding={isExpanding}
 431                                     isRewriting={isRewriting}
 432                                     rewriteStyles={rewriteStyles}
 433                                     onHoverEnter={handleItemMouseEnter}
 434                                     onHoverLeave={handleItemMouseLeave}
 435                                     onSelectSection={handleSectionClick}
 436                                     onEditSection={handleSectionEdit}
 437                                     onSummarize={handleSummarize}
 438                                     onExpand={handleExpand}
 439                                     onRewrite={handleRewrite}
 440                                 />
 441                             );
 442                         }
 443 
 444                         return null;
 445                     })}
 446                 </div>
 447             )}
 448         </div>
 449     );
 450 };
