  91       attributes: {
  92         class: cn(PROSE_CLASSES, editorClassName),
  93       },
  94       handlePaste: (view, event, slice): boolean => {
  95         const text = event.clipboardData?.getData('text/plain');
  96         const html = event.clipboardData?.getData('text/html');
  97 
  98         if (html) {
  99           void handleHtmlPaste(editor!, html);
 100           return true;
 101         }
 102 
 103         if (text) {
 104           void handlePlainPaste(editor!, text, markdownService);
 105           return true;
 106         }
 107 
 108         return false;
 109       },
 110     },
 111     immediatelyRender: false,
 112   });
