 114   // Sync external content changes
 115   React.useEffect(() => {
 116     if (!editor || editor.isDestroyed) return;
 117 
 118     const currentHtml = editor.getHTML();
 119     const newHtml = markdownService.toHtml(content);
 120 
 121     // Only update if content is actually different to prevent cursor jumping
 122     // and only if the change came from outside (not while typing)
 123     if (newHtml !== currentHtml && !editor.isFocused) {
 124       editor.commands.setContent(newHtml, false);
